style.css:
/* Fonte parecida com Frutiger: usando "Segoe UI" e "Open Sans" como fallback */
body, input, button, select, textarea {
  font-family: "Segoe UI", "Open Sans", Arial, sans-serif !important;
  background: linear-gradient(to bottom, #a0cfff, #d0e7ff) !important; /* fundo azul claro suave */
  color: #000000 !important;
  transition: background 0.3s ease;
}

/* Botões com bolhas e azul claro */
button, input[type="button"], input[type="submit"] {
  background: rgba(135, 206, 250, 0.8) !important;
  border-radius: 30px !important;
  border: none !important;
  padding: 10px 25px !important;
  color: #fff !important;
  font-weight: 600 !important;
  box-shadow: 0 4px 15px rgba(135, 206, 250, 0.7) !important;
  cursor: pointer !important;
  transition: background 0.3s ease, box-shadow 0.3s ease;
}

/* Hover efeito "bolha" brilhante */
button:hover, input[type="button"]:hover, input[type="submit"]:hover {
  background: rgba(135, 206, 250, 1) !important;
  box-shadow: 0 6px 25px rgba(135, 206, 250, 1) !important;
}

/* Links com brilho azul */
a {
  color: #3399ff !important;
  text-decoration: none !important;
  text-shadow: 0 0 8px rgba(51, 153, 255, 0.7);
  transition: text-shadow 0.3s ease;
}

a:hover {
  text-shadow: 0 0 15px rgba(51, 153, 255, 1);
  text-decoration: underline !important;
}

/* Caixas com efeito translúcido */
div, section, main, header, footer {
  background: rgba(255, 255, 255, 0.15) !important;
  border-radius: 12px !important;
  border: 1px solid rgba(255, 255, 255, 0.3) !important;
  box-shadow: 0 0 20px rgba(255, 255, 255, 0.1) !important;
  backdrop-filter: blur(10px) !important;
}

/* Remover fundo padrão dos menus suspensos e inputs */
select, input, textarea {
  background: rgba(255, 255, 255, 0.2) !important;
  border-radius: 8px !important;
  border: 1px solid rgba(255, 255, 255, 0.4) !important;
  color: #000 !important;
  padding: 5px 10px !important;
  box-shadow: 0 0 10px rgba(255, 255, 255, 0.15) inset !important;
}
